        FamousDua(37, "مہمان کی دعا", "کھانا پینا", "أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ وَصَلَّتْ عَلَيْكُمُ الْمَلَائِكَةُ", "Aftara 'indakumus-sa'imun...", "تمہارے پاس روزے دار افطار کریں، نیک لوگ تمہارا کھانا کھائیں اور فرشتے تمہارے لیے دعا کریں۔", "ابوداؤد: 3854"),
        FamousDua(38, "دعوت پر جانے کی دعا", "کھانا پینا", "اللَّهُمَّ اغْفِرْ لَهُمْ وَارْحَمْهُمْ وَبَارِكْ لَهُمْ فِيمَا رَزَقْتَهُمْ", "Allahummaghfir lahum warhamhum wa barik lahum...", "اے اللہ انہیں بخش دے، رحم فرما اور ان کے رزق میں برکت دے۔", "مسلم"),
        FamousDua(39, "پہلا پھل دیکھنے کی دعا", "کھانا پینا", "اللَّهُمَّ بَارِكْ لَنَا فِي ثَمَرِنَا وَبَارِكْ لَنَا فِي مَدِينَتِنَا", "Allahumma barik lana fi thamarina...", "اے اللہ ہمارے پھلوں میں اور ہمارے شہر میں برکت عطا فرما۔", "مسلم: 1373"),
        FamousDua(40, "روزہ افطار کی دعا", "کھانا پینا", "ذَهَبَ الظَّمَأُ وَابْتَلَّتِ الْعُرُوقُ وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ", "Dhahabaz-zama'u wabtallatil-'uruqu...", "پیاس ختم ہوئی، رگیں تر ہو گئیں اور ان شاء اللہ اجر ثابت ہو گیا۔", "ابوداؤد: 2357"),
        FamousDua(41, "دنیا و آخرت کی بھلائی کی دعا", "قرآنی دعائیں", "رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ", "Rabbana atina fid-dunya hasanatan...", "اے ہمارے رب! ہمیں دنیا میں بھلائی دے اور آخرت میں بھی بھلائی دے اور ہمیں آگ کے عذاب سے بچا۔", "قرآن 2:201"),
        FamousDua(42, "ثابت قدم رہنے کی دعا", "قرآنی دعائیں", "رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً", "Rabbana la tuzigh qulubana ba'da idh hadaitana...", "اے ہمارے رب! ہدایت کے بعد ہمارے دلوں کو ٹیڑھا نہ کر اور ہمیں اپنی رحمت عطا فرما۔", "قرآن 3:8"),
        FamousDua(43, "مغفرت کی دعا", "قرآنی دعائیں", "رَبَّنَا اغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِي أَمْرِنَا وَثَبِّتْ أَقْدَامَنَا", "Rabbanaghfir lana dhunubana wa israfana...", "اے ہمارے رب! ہمارے گناہ اور ہمارے کام میں زیادتی کو معاف فرما اور ہمارے قدم ثابت رکھ۔", "قرآن 3:147"),
        FamousDua(44, "ظلم سے حفاظت کی دعا", "قرآنی دعائیں", "رَبَّنَا ظَلَمْنَا أَنْفُسَنَا وَإِنْ لَمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ", "Rabbana zalamna anfusana...", "اے ہمارے رب! ہم نے اپنی جانوں پر ظلم کیا، اگر تو نے ہمیں نہ بخشا تو ہم نقصان والوں میں سے ہوں گے۔", "قرآن 7:23"),
        FamousDua(45, "والدین کے لیے دعا", "قرآنی دعائیں", "رَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ", "Rabbanaghfir li wa liwalidayya...", "اے ہمارے رب! مجھے، میرے والدین اور مومنین کو حساب کے دن بخش دے۔", "قرآن 14:41"),
        FamousDua(46, "اولاد کے لیے دعا", "قرآنی دعائیں", "رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ", "Rabbana hab lana min azwajina wa dhurriyatina...", "اے ہمارے رب! ہمیں ہماری بیویوں اور اولاد سے آنکھوں کی ٹھنڈک عطا فرما۔", "قرآن 25:74"),
        FamousDua(47, "جہنم سے بچاؤ کی دعا", "قرآنی دعائیں", "رَبَّنَا اصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ إِنَّ عَذَابَهَا كَانَ غَرَامًا", "Rabbanasrif 'anna adhaba Jahannama...", "اے ہمارے رب! ہم سے جہنم کا عذاب ہٹا دے، بے شک اس کا عذاب چمٹ جانے والا ہے۔", "قرآن 25:65"),
        FamousDua(48, "علم میں اضافے کی دعا", "قرآنی دعائیں", "رَبِّ زِدْنِي عِلْمًا", "Rabbi zidni 'ilma", "اے میرے رب! میرے علم میں اضافہ فرما۔", "قرآن 20:114"),
        FamousDua(49, "کام آسان ہونے کی دعا", "قرآنی دعائیں", "رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي", "Rabbishrah li sadri wa yassir li amri", "اے میرے رب! میرا سینہ کھول دے اور میرا کام آسان کر دے۔", "قرآن 20:25-26"),
        FamousDua(50, "بخشش کی دعا", "قرآنی دعائیں", "رَبَّنَا آمَنَّا فَاغْفِرْ لَنَا وَارْحَمْنَا وَأَنْتَ خَيْرُ الرَّاحِمِينَ", "Rabbana amanna faghfir lana warhamna...", "اے ہمارے رب ہم ایمان لائے، ہمیں بخش دے اور رحم فرما تو سب سے بہتر رحم کرنے والا ہے۔", "قرآن 23:109"),
        FamousDua(51, "فتنہ سے بچاؤ کی دعا", "قرآنی دعائیں", "رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِلْقَوْمِ الظَّالِمِينَ", "Rabbana la taj'alna fitnatan lil-qawmiz-zalimin", "اے ہمارے رب! ہمیں ظالم قوم کے لیے فتنہ نہ بنا۔", "قرآن 10:85"),
