        FamousDua(53, "صبر کی دعا", "قرآنی دعائیں", "رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَتَوَفَّنَا مُسْلِمِينَ", "Rabbana afrigh 'alaina sabran wa tawaffana muslimin", "اے ہمارے رب! ہم پر صبر انڈیل دے اور ہمیں مسلمان ہونے کی حالت میں وفات دے۔", "قرآن 7:126"),
        FamousDua(54, "قبولیت کی دعا", "قرآنی دعائیں", "رَبَّنَا تَقَبَّلْ مِنَّا إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ", "Rabbana taqabbal minna innaka Antas-Sami'ul-'Alim", "اے ہمارے رب ہم سے قبول فرما، بے شک تو سننے والا جاننے والا ہے۔", "قرآن 2:127"),
        FamousDua(55, "ہدایت کی دعا", "قرآنی دعائیں", "رَبَّنَا إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِي لِلْإِيمَانِ أَنْ آمِنُوا بِرَبِّكُمْ فَآمَنَّا", "Rabbana innana sami'na munadiyan yunadi lil-imani...", "اے ہمارے رب ہم نے ایک منادی کو سنا جو ایمان کی دعوت دیتا تھا تو ہم ایمان لے آئے۔", "قرآن 3:193"),
        FamousDua(56, "ظالم سے نجات کی دعا", "قرآنی دعائیں", "رَبَّنَا أَخْرِجْنَا مِنْ هَذِهِ الْقَرْيَةِ الظَّالِمِ أَهْلُهَا", "Rabbana akhrijna min hadhihil-qaryatiz-zalimi ahluha", "اے ہمارے رب ہمیں اس بستی سے نکال جس کے رہنے والے ظالم ہیں۔", "قرآن 4:75"),
        FamousDua(57, "نیک انجام کی دعا", "قرآنی دعائیں", "رَبَّنَا لَا تَجْعَلْنَا مَعَ الْقَوْمِ الظَّالِمِينَ", "Rabbana la taj'alna ma'al-qawmiz-zalimin", "اے ہمارے رب ہمیں ظالم لوگوں کے ساتھ شامل نہ کر۔", "قرآن 7:47"),
        FamousDua(58, "مغفرت و رحمت کی دعا", "قرآنی دعائیں", "رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ", "Rabbanaghfir lana wa li-ikhwaninal-ladhina sabaquna bil-iman", "اے ہمارے رب ہمیں اور ہمارے ان بھائیوں کو بخش دے جو ایمان میں ہم سے آگے نکل گئے۔", "قرآن 59:10"),
        FamousDua(59, "توکل کی دعا", "قرآنی دعائیں", "رَبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ الْمَصِيرُ", "Rabbana 'alaika tawakkalna...", "اے ہمارے رب تجھ پر ہم نے بھروسہ کیا اور تیری طرف رجوع کیا اور تیری ہی طرف لوٹنا ہے۔", "قرآن 60:4"),
        FamousDua(60, "نور کی دعا", "قرآنی دعائیں", "رَبَّنَا أَتْمِمْ لَنَا نُورَنَا وَاغْفِرْ لَنَا إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ", "Rabbana atmim lana nurana waghfir lana...", "اے ہمارے رب ہمارا نور ہمارے لیے مکمل کر دے اور ہمیں بخش دے۔", "قرآن 66:8"),
        FamousDua(61, "جامع مغفرت کی دعا", "حفاظت / مغفرت", "اللَّهُمَّ اغْفِرْ لِي ذَنْبِي كُلَّهُ، دِقَّهُ وَجِلَّهُ، وَأَوَّلَهُ وَآخِرَهُ", "Allahummaghfir li dhanbi kullahu diqqahu wa jillahu...", "اے اللہ میرے تمام گناہ بخش دے، چھوٹے بڑے، پہلے اور پچھلے۔", "مسلم: 483"),
