        FamousDua(65, "نظر بد سے حفاظت", "حفاظت / مغفرت", "أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ", "A'udhu bikalimatillahit-tammati...", "میں ہر شیطان، زہریلے جانور اور ہر لگنے والی نظر سے اللہ کے مکمل کلمات کی پناہ میں آتا ہوں۔", "بخاری: 3371"),
        FamousDua(66, "بیماری سے شفا کی دعا", "حفاظت / مغفرت", "اللَّهُمَّ رَبَّ النَّاسِ، أَذْهِبِ الْبَأْسَ، اشْفِ أَنْتَ الشَّافِي", "Allahumma Rabban-nas, adhhibil-ba'sa, ishfi Antash-Shafi", "اے لوگوں کے رب! تکلیف دور کر دے، شفا دے تو ہی شفا دینے والا ہے۔", "بخاری: 5742"),
        FamousDua(67, "ہر بیماری سے شفا", "حفاظت / مغفرت", "أَسْأَلُ اللَّهَ الْعَظِيمَ رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يَشْفِيَكَ", "As'alullahal-'Azima Rabbal-'Arshil-'Azimi an yashfiyak", "میں عظمت والے اللہ سے، عرش عظیم کے رب سے سوال کرتا ہوں کہ وہ تجھے شفا دے۔", "ترمذی: 2083"),
        FamousDua(68, "جادو اور شر سے حفاظت", "حفاظت / مغفرت", "بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ", "Bismillahil-ladhi la yadurru ma'asmihi shai'un...", "اللہ کے نام سے جس کے نام سے زمین و آسمان میں کوئی چیز نقصان نہیں پہنچا سکتی۔", "ترمذی: 3388"),
        FamousDua(69, "غم و پریشانی سے حفاظت", "حفاظت / مغفرت", "حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ", "Hasbunallahu wa ni'mal wakil", "ہمیں اللہ کافی ہے اور وہ بہترین کارساز ہے۔", "قرآن 3:173"),
