        FamousDua(71, "دشمن سے حفاظت کی دعا", "حفاظت / مغفرت", "اللَّهُمَّ إِنَّا نَجْعَلُكَ فِي نُحُورِهِمْ وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ", "Allahumma inna naj'aluka fi nuhurihim...", "اے اللہ ہم تجھے ان کے مقابلے میں کرتے ہیں اور ان کے شر سے تیری پناہ مانگتے ہیں۔", "ابوداؤد: 1537"),
        FamousDua(72, "حسد سے پناہ", "حفاظت / مغفرت", "وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ", "Wa min sharri hasidin idha hasad", "اور حاسد کے شر سے جب وہ حسد کرے۔", "قرآن 113:5"),
        FamousDua(73, "دل کی حفاظت کی دعا", "حفاظت / مغفرت", "يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ", "Ya muqallibal-qulubi thabbit qalbi 'ala dinik", "اے دلوں کو پھیرنے والے! میرے دل کو اپنے دین پر ثابت رکھ۔", "ترمذی: 2140"),
        FamousDua(74, "ایمان پر خاتمہ کی دعا", "حفاظت / مغفرت", "اللَّهُمَّ اجْعَلْ خَيْرَ عُمْرِي آخِرَهُ وَخَيْرَ عَمَلِي خَوَاتِمَهُ", "Allahummaj'al khaira 'umri akhirahu...", "اے اللہ میری عمر کا بہترین حصہ آخر بنا اور بہترین عمل خاتمہ والا بنا۔", "طبرانی"),
        FamousDua(75, "گناہوں سے معافی کی دعا", "حفاظت / مغفرت", "رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ", "Rabbighfir li wa tub 'alayya...", "اے میرے رب مجھے بخش دے اور میری توبہ قبول کر، تو ہی توبہ قبول کرنے والا رحم والا ہے۔", "ابوداؤد: 1516"),
        FamousDua(76, "جسمانی حفاظت کی دعا", "حفاظت / مغفرت", "اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي", "Allahumma 'afini fi badani, Allahumma 'afini fi sam'i...", "اے اللہ میرے جسم میں، میرے کان میں، میری آنکھ میں عافیت دے۔", "ابوداؤد: 5090"),
        FamousDua(77, "قرض سے بچاؤ کی دعا", "حفاظت / مغفرت", "اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ", "Allahummakfini bihalalika 'an haramika...", "اے اللہ مجھے حلال کے ساتھ حرام سے کافی کر دے اور اپنے فضل سے اپنے سوا سے بے نیاز کر دے۔", "ترمذی: 3563"),
        FamousDua(78, "اولاد کی حفاظت کی دعا", "حفاظت / مغفرت", "أُعِيذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ", "U'idhukuma bikalimatillahit-tammati...", "میں تم دونوں کو اللہ کے مکمل کلمات کی پناہ میں دیتا ہوں ہر شیطان سے۔", "بخاری: 3371"),
        FamousDua(79, "گھر کی حفاظت کی دعا", "حفاظت / مغفرت", "حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ", "Hasbiyallahu la ilaha illa Huwa...", "مجھے اللہ کافی ہے، اس کے سوا کوئی معبود نہیں، اسی پر بھروسہ ہے اور وہ عرش عظیم کا رب ہے۔", "قرآن 9:129"),
        FamousDua(80, "شیطان سے حفاظت", "حفاظت / مغفرت", "أَعُوذُ بِاللَّهِ السَّمِيعِ الْعَلِيمِ مِنَ الشَّيْطَانِ الرَّجِيمِ", "A'udhu billahis-sami'il-'alimi minash-shaitanir-rajim", "میں سننے جاننے والے اللہ کی پناہ مانگتا ہوں مردود شیطان سے۔", "ابوداؤد"),
        FamousDua(81, "مشکل اور پریشانی کی دعا", "مشکل / پریشانی", "لَا إِلَهَ إِلَّا اللَّهُ الْعَظِيمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ", "La ilaha illallahul-'Azimul-Halim...", "اللہ کے سوا کوئی معبود نہیں جو عظمت والا بردبار ہے، عرش عظیم کا رب ہے۔", "بخاری: 6346"),
        FamousDua(82, "غم سے نجات - یونس علیہ السلام کی دعا", "مشکل / پریشانی", "لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ", "La ilaha illa Anta subhanaka inni kuntu minaz-zalimin", "تیرے سوا کوئی معبود نہیں تو پاک ہے، میں ہی ظالموں میں سے ہوں۔", "قرآن 21:87"),
        FamousDua(83, "قرض اترنے کی دعا", "مشکل / پریشانی", "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ", "Allahumma inni a'udhu bika minal-hammi wal-hazan...", "اے اللہ میں فکر و غم، عاجزی و سستی، بزدلی و بخل اور قرض کے غلبہ سے تیری پناہ مانگتا ہوں۔", "ابوداؤد: 1555"),
        FamousDua(84, "رزق میں برکت کی دعا", "مشکل / پریشانی", "اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا وَرِزْقًا طَيِّبًا وَعَمَلًا مُتَقَبَّلًا", "Allahumma inni as'aluka 'ilman nafi'an wa rizqan tayyiban...", "اے اللہ میں تجھ سے نفع دینے والا علم، پاک رزق اور قبول عمل کا سوال کرتا ہوں۔", "ابن ماجہ: 925"),
        FamousDua(85, "علم میں اضافے کی دعا", "مشکل / پریشانی", "اللَّهُمَّ انْفَعْنِي بِمَا عَلَّمْتَنِي وَعَلِّمْنِي مَا يَنْفَعُنِي وَزِدْنِي عِلْمًا", "Allahummanfa'ni bima 'allamtani wa 'allimni ma yanfa'uni wa zidni 'ilma", "اے اللہ جو تو نے سکھایا اس سے مجھے نفع دے، جو نفع دے وہ سکھا اور علم بڑھا۔", "ترمذی: 3599"),
        FamousDua(86, "امتحان میں آسانی کی دعا", "مشکل / پریشانی", "اللَّهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلًا", "Allahumma la sahla illa ma ja'altahu sahla...", "اے اللہ آسان وہی ہے جسے تو آسان کرے، اور تو مشکل کو جب چاہے آسان کر دے۔", "ابن حبان"),
        FamousDua(87, "نکاح کے لیے دعا", "مشکل / پریشانی", "رَبِّ إِنِّي لِمَا أَنْزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيرٌ", "Rabbi inni lima anzalta ilayya min khairin faqir", "اے میرے رب! جو خیر بھی تو میری طرف نازل کرے میں اس کا محتاج ہوں۔", "قرآن 28:24"),
        FamousDua(88, "اولاد صالح کے لیے دعا", "مشکل / پریشانی", "رَبِّ هَبْ لِي مِنْ لَدُنْكَ ذُرِّيَّةً طَيِّبَةً إِنَّكَ سَمِيعُ الدُّعَاءِ", "Rabbi hab li min ladunka dhurriyyatan tayyibatan...", "اے میرے رب مجھے اپنی طرف سے پاک اولاد عطا فرما، تو دعا سننے والا ہے۔", "قرآن 3:38"),
        FamousDua(89, "والدین کے لیے دعا", "مشکل / پریشانی", "رَبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا", "Rabbirhamhuma kama rabbayani saghira", "اے میرے رب ان پر رحم فرما جیسے انہوں نے بچپن میں میری پرورش کی۔", "قرآن 17:24"),
        FamousDua(90, "والدین کی مغفرت کی دعا", "حفاظت / مغفرت", "رَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ", "Rabbanaghfir li wa liwalidayya wa lil-mu'minina...", "اے رب مجھے اور میرے والدین کو اور مومنین کو بخش دے حساب کے دن۔", "قرآن 14:41"),
        FamousDua(91, "گھر میں برکت اور محبت کی دعا", "گھر / مسجد", "رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا", "Rabbana hab lana min azwajina wa dhurriyatina qurrata a'yun...", "ہمیں بیویوں اور اولاد سے آنکھوں کی ٹھنڈک دے اور ہمیں متقیوں کا امام بنا۔", "قرآن 25:74"),
        FamousDua(92, "رزق حلال کی دعا", "مشکل / پریشانی", "اللَّهُمَّ ارْزُقْنِي رِزْقًا حَلَالًا طَيِّبًا وَبَارِكْ لِي فِيهِ", "Allahummarzuqni rizqan halalan tayyiban wa barik li fihi", "اے اللہ مجھے حلال پاک رزق عطا فرما اور اس میں برکت دے۔", "دعا"),
        FamousDua(93, "دنیا کی محبت سے بچنے کی دعا", "مشکل / پریشانی", "اللَّهُمَّ لَا تَجْعَلِ الدُّنْيَا أَكْبَرَ هَمِّنَا", "Allahumma la taj'alid-dunya akbara hammina", "اے اللہ دنیا کو ہمارا سب سے بڑا غم نہ بنا۔", "ترمذی"),
        FamousDua(94, "قبول دعا کی دعا", "مشکل / پریشانی", "اللَّهُمَّ إِنِّي أَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ وَعَزَائِمَ مَغْفِرَتِكَ", "Allahumma inni as'aluka mujibati rahmatika wa 'aza'ima maghfiratik", "اے اللہ میں تجھ سے تیری رحمت کے اسباب اور مغفرت کے عزائم کا سوال کرتا ہوں۔", "ابن ماجہ: 1385"),
        FamousDua(95, "ہدایت پر قائم رہنے کی دعا", "حفاظت / مغفرت", "اللَّهُمَّ اهْدِنِي وَسَدِّدْنِي", "Allahummahdini wa saddidni", "اے اللہ مجھے ہدایت دے اور سیدھا رکھ۔", "مسلم: 2725"),
        FamousDua(96, "موت کے وقت کلمہ نصیب ہو", "حفاظت / مغفرت", "اللَّهُمَّ اجْعَلْ آخِرَ كَلَامِي لَا إِلَهَ إِلَّا اللَّهُ", "Allahummaj'al akhira kalami La ilaha illallah", "اے اللہ میرا آخری کلام لا الہ الا اللہ بنا دے۔", "ابوداؤد"),
        FamousDua(97, "قبر کے عذاب سے پناہ", "حفاظت / مغفرت", "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ وَعَذَابِ جَهَنَّمَ", "Allahumma inni a'udhu bika min 'adhabil-qabri wa 'adhabi Jahannam", "اے اللہ میں قبر کے عذاب اور جہنم کے عذاب سے تیری پناہ مانگتا ہوں۔", "مسلم: 588"),
        FamousDua(98, "دل کی پاکیزگی کی دعا", "مشکل / پریشانی", "اللَّهُمَّ طَهِّرْ قَلْبِي مِنَ النِّفَاقِ وَعَمَلِي مِنَ الرِّيَاءِ", "Allahumma tahhir qalbi minan-nifaqi wa 'amali minar-riya'", "اے اللہ میرے دل کو نفاق سے اور عمل کو ریا سے پاک کر دے۔", "دعا"),
        FamousDua(99, "امت کے لیے دعا", "مشکل / پریشانی", "اللَّهُمَّ أَصْلِحْ أُمَّةَ مُحَمَّدٍ، اللَّهُمَّ فَرِّجْ عَنْ أُمَّةِ مُحَمَّدٍ", "Allahumma aslih ummata Muhammad, Allahumma farrij 'an ummati Muhammad", "اے اللہ امت محمدیہ کی اصلاح فرما، ان کی پریشانیاں دور فرما۔", "دعا"),
        FamousDua(100, "خاتمہ - جامع دعا", "قرآنی دعائیں", "رَبَّنَا تَقَبَّلْ مِنَّا إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ وَتُبْ عَلَيْنَا إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ", "Rabbana taqabbal minna innaka Antas-Sami'ul-'Alim wa tub 'alaina...", "اے ہمارے رب ہم سے قبول فرما، تو سننے والا جاننے والا ہے، اور ہماری توبہ قبول فرما۔", "قرآن 2:127-128")
    )
}
